                students.ifsc_code,
                students.guardian_name,
                students.guardian_relation,
                students.guardian_phone,
                students.guardian_address,
                students.is_active,
                students.created_at,
                students.updated_at,
                students.father_name,
                students.rte,
                students.gender,
                student_session.is_active as session_is_active
            FROM students
            JOIN student_session ON student_session.student_id = students.id
            JOIN classes ON student_session.class_id = classes.id
            JOIN sections ON sections.id = student_session.section_id
            JOIN programs ON programs.id = student_session.program_id
            LEFT JOIN categories ON students.category_id = categories.id
            WHERE student_session.session_id = '21'
            AND student_session.class_id = '33'
            AND student_session.section_id = '11'
            AND student_session.program_id = '7'
            AND COALESCE(student_session.is_leave, 0) = 0
            AND COALESCE(student_session.is_graduated, 0) = 0
            AND NOT EXISTS (
                SELECT 1 FROM student_session ps
                WHERE ps.student_id = students.id
                AND ps.session_id = '27'
                AND ps.class_id = '34'
                AND ps.section_id = '11'
                AND ps.program_id = '7'
            )
            ORDER BY students.id SQL: SELECT 
                students.id,
                classes.id AS class_id,
                student_session.id as student_session_id,
                classes.class,
                sections.id AS section_id,
                sections.section,
                programs.id AS program_id,
                programs.title AS program,
                students.admission_no,
                students.roll_no,
                students.admission_date,
                students.firstname,
                students.middlename,
                students.lastname,
                students.image,
                students.mobileno,
                students.email,
                students.state,
                students.city,
                students.pincode,
                students.religion,
                students.dob,
                students.current_address,
                students.permanent_address,
                IFNULL(students.category_id, 0) as category_id,
                IFNULL(categories.category, '') as category,
                students.adhar_no,
                students.samagra_id,
                students.bank_account_no,
                students.bank_name,
                students.ifsc_code,
                students.guardian_name,
                students.guardian_relation,
                students.guardian_phone,
                students.guardian_address,
                students.is_active,
                students.created_at,
                students.updated_at,
                students.father_name,
                students.rte,
                students.gender,
                student_session.is_active as session_is_active
            FROM students
            JOIN student_session ON student_session.student_id = students.id
            JOIN classes ON student_session.class_id = classes.id
            JOIN sections ON sections.id = student_session.section_id
            JOIN programs ON programs.id = student_session.program_id
            LEFT JOIN categories ON students.category_id = categories.id
            WHERE student_session.session_id = '21'
            AND student_session.class_id = '33'
            AND student_session.section_id = '11'
            AND student_session.program_id = '7'
            AND COALESCE(student_session.is_leave, 0) = 0
            AND COALESCE(student_session.is_graduated, 0) = 0
            AND NOT EXISTS (
                SELECT 1 FROM student_session ps
                WHERE ps.student_id = students.id
                AND ps.session_id = '27'
                AND ps.class_id = '34'
                AND ps.section_id = '11'
                AND ps.program_id = '7'
            )
            ORDER BY students.id
